import { SynapseEnhancedError } from "./http.ts";
import { ErrorCode } from "./error-codes.ts";

export enum ErrorAction {
    RETRY = "retry",
    REFRESH_TOKEN = "refresh_token",
    WAIT_RETRY = "wait_retry",
    REJECT = "reject",
    NOTIFY = "notify",
}

export interface ErrorHandlingStrategy {
    action: ErrorAction;
    retryAfter?: number;
    message?: string;
}

export interface ErrorContext {
    endpoint: string;
    method: string;
    attemptNumber: number;
    timestamp: number;
    userContext?: Record<string, unknown>;
}

export interface ErrorHandlerConfig {
    maxRetries?: number;
    tokenRefreshEnabled?: boolean;
    defaultWaitTime?: number;
    enableMetrics?: boolean;
}

export class ErrorHandler {
    private static readonly ERROR_STRATEGIES: Map<ErrorCode, ErrorHandlingStrategy> = new Map([
        [ErrorCode.UNKNOWN_TOKEN, { action: ErrorAction.REFRESH_TOKEN, message: "Token expired or invalid" }],
        [ErrorCode.INVALID_PARAM, { action: ErrorAction.REJECT, message: "Invalid request parameters" }],
        [ErrorCode.FORBIDDEN, { action: ErrorAction.REJECT, message: "Access forbidden" }],
        [ErrorCode.NOT_FOUND, { action: ErrorAction.REJECT, message: "Resource not found" }],
        [ErrorCode.RATE_LIMITED, { action: ErrorAction.WAIT_RETRY, retryAfter: 1000, message: "Rate limited" }],
        [ErrorCode.LIMIT_EXCEEDED, { action: ErrorAction.WAIT_RETRY, retryAfter: 2000, message: "Limit exceeded" }],
        [ErrorCode.THROTTLED, { action: ErrorAction.WAIT_RETRY, retryAfter: 1500, message: "Throttled" }],
        [ErrorCode.TIMEOUT, { action: ErrorAction.RETRY, message: "Request timed out" }],
        [ErrorCode.NET_ERROR, { action: ErrorAction.RETRY, message: "Network error" }],
        [ErrorCode.UNAVAILABLE, { action: ErrorAction.WAIT_RETRY, retryAfter: 3000, message: "Service unavailable" }],
        [
            ErrorCode.SERVICE_UNAVAILABLE,
            { action: ErrorAction.WAIT_RETRY, retryAfter: 3000, message: "Service unavailable" },
        ],
        [ErrorCode.INTERNAL_ERROR, { action: ErrorAction.RETRY, message: "Internal server error" }],
    ]);

    private static readonly ERROR_COUNT: Map<string, number> = new Map();
    private static readonly LAST_ERROR_TIME: Map<string, number> = new Map();

    public static handleError(
        error: SynapseEnhancedError,
        context: ErrorContext,
        config?: ErrorHandlerConfig,
    ): ErrorHandlingStrategy {
        const key = `${context.method}:${context.endpoint}`;
        const currentCount = this.ERROR_COUNT.get(key) ?? 0;

        const strategy = this.getStrategy(error.code);

        if (error.statusCode >= 400 && error.statusCode < 500) {
            if (error.statusCode === 401) {
                this.ERROR_COUNT.set(key, currentCount + 1);
                this.LAST_ERROR_TIME.set(key, Date.now());
                return {
                    action: ErrorAction.REFRESH_TOKEN,
                    message: "Authentication required",
                };
            }

            if (error.statusCode === 403) {
                return {
                    action: ErrorAction.REJECT,
                    message: "Access denied",
                };
            }

            if (error.statusCode === 429) {
                const waitTime = this.calculateBackoff(currentCount, config?.defaultWaitTime ?? 1000);
                this.ERROR_COUNT.set(key, currentCount + 1);
                return {
                    action: ErrorAction.WAIT_RETRY,
                    retryAfter: waitTime,
                    message: "Rate limit exceeded",
                };
            }

            return {
                action: ErrorAction.REJECT,
                message: error.message,
            };
        }

        if (error.statusCode >= 500) {
            this.ERROR_COUNT.set(key, currentCount + 1);
            this.LAST_ERROR_TIME.set(key, Date.now());

            if (context.attemptNumber >= (config?.maxRetries ?? 3)) {
                return {
                    action: ErrorAction.REJECT,
                    message: `Max retries exceeded for ${context.endpoint}`,
                };
            }

            return {
                ...strategy,
                retryAfter: strategy.retryAfter ?? this.calculateBackoff(context.attemptNumber),
            };
        }

        return strategy;
    }

    public static getStrategy(errorCode: ErrorCode): ErrorHandlingStrategy {
        return this.ERROR_STRATEGIES.get(errorCode) ?? { action: ErrorAction.RETRY };
    }

    public static registerStrategy(errorCode: ErrorCode, strategy: ErrorHandlingStrategy): void {
        this.ERROR_STRATEGIES.set(errorCode, strategy);
    }

    public static shouldRetry(error: SynapseEnhancedError): boolean {
        return error.retryable || error.statusCode >= 500;
    }

    public static async executeWithRetry<T>(
        fn: () => Promise<T>,
        context: Omit<ErrorContext, "attemptNumber" | "timestamp">,
        config?: ErrorHandlerConfig,
    ): Promise<T> {
        let attempt = 0;
        let lastError: SynapseEnhancedError | null = null;

        while (attempt <= (config?.maxRetries ?? 3)) {
            try {
                return await fn();
            } catch (error) {
                if (error instanceof SynapseEnhancedError) {
                    lastError = error;
                    const handling = this.handleError(
                        error,
                        {
                            ...context,
                            attemptNumber: attempt,
                            timestamp: Date.now(),
                        },
                        config,
                    );

                    if (handling.action === ErrorAction.REJECT) {
                        throw error;
                    }

                    if (handling.action === ErrorAction.REFRESH_TOKEN) {
                        throw error;
                    }

                    if (handling.action === ErrorAction.WAIT_RETRY && handling.retryAfter) {
                        await this.sleep(handling.retryAfter);
                    }
                } else {
                    throw error;
                }
            }
            attempt++;
        }

        throw lastError;
    }

    public static resetErrorCount(endpoint: string, method: string): void {
        const key = `${method}:${endpoint}`;
        this.ERROR_COUNT.delete(key);
        this.LAST_ERROR_TIME.delete(key);
    }

    public static resetAllErrorCounts(): void {
        this.ERROR_COUNT.clear();
        this.LAST_ERROR_TIME.clear();
    }

    public static getErrorStats(): Map<string, { count: number; lastError: number | undefined }> {
        const stats = new Map();

        for (const [key, count] of this.ERROR_COUNT.entries()) {
            stats.set(key, {
                count,
                lastError: this.LAST_ERROR_TIME.get(key),
            });
        }

        return stats;
    }

    private static calculateBackoff(attemptNumber: number, baseDelay = 1000): number {
        const exponentialDelay = baseDelay * Math.pow(2, attemptNumber);
        const jitter = Math.random() * 0.3 * exponentialDelay;
        return Math.min(exponentialDelay + jitter, 30000);
    }

    private static sleep(ms: number): Promise<void> {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    public static createUserError(message: string, code: ErrorCode = ErrorCode.UNKNOWN): SynapseEnhancedError {
        return new SynapseEnhancedError(message, code, undefined, 400, false);
    }

    public static createServerError(message: string): SynapseEnhancedError {
        return new SynapseEnhancedError(message, ErrorCode.INTERNAL_ERROR, undefined, 500, true);
    }

    public static createNetworkError(originalError?: Error): SynapseEnhancedError {
        return new SynapseEnhancedError(
            originalError?.message ?? "Network error occurred",
            ErrorCode.NET_ERROR,
            { originalError: String(originalError) },
            0,
            true,
        );
    }

    public static wrapError(error: unknown, context?: string): SynapseEnhancedError {
        if (error instanceof SynapseEnhancedError) {
            return error;
        }

        if (error instanceof Error) {
            return new SynapseEnhancedError(
                context ? `${context}: ${error.message}` : error.message,
                ErrorCode.UNKNOWN,
                { stack: error.stack },
                0,
                false,
            );
        }

        return new SynapseEnhancedError(
            context ?? "Unknown error",
            ErrorCode.UNKNOWN,
            { error: String(error) },
            0,
            false,
        );
    }
}
